import { mkdirSync, writeFileSync } from "node:fs";
import { SoundSystem, EFFECTS } from "./WebSoundSynthesizer.js";

const rate = 22050;
const synth = new SoundSystem();
synth.context = {
  sampleRate: rate,
  createBuffer(_channels, count) {
    const data = new Float32Array(count);
    return { data, getChannelData: () => data };
  },
};
mkdirSync(new URL("../assets/audio/", import.meta.url), { recursive: true });
let mapping =
  "// Generated by npm run assets:audio from the original game sound definitions.\n";
mapping +=
  "export const soundAssets: Record<string, { source: number; cooldown: number }> = {\n";
for (const [key, effect] of Object.entries(EFFECTS)) {
  // Seed noise so regenerating these checked-in assets produces stable output.
  let seed = 42;
  const random = Math.random;
  Math.random = () =>
    ((seed = (Math.imul(seed, 1664525) + 1013904223) | 0) >>> 0) / 4294967296;
  const { data } = synth._synthesize(effect.notes);
  Math.random = random;
  const wav = Buffer.alloc(44 + data.length * 2);
  wav.write("RIFF", 0);
  wav.writeUInt32LE(wav.length - 8, 4);
  wav.write("WAVEfmt ", 8);
  wav.writeUInt32LE(16, 16);
  wav.writeUInt16LE(1, 20);
  wav.writeUInt16LE(1, 22);
  wav.writeUInt32LE(rate, 24);
  wav.writeUInt32LE(rate * 2, 28);
  wav.writeUInt16LE(2, 32);
  wav.writeUInt16LE(16, 34);
  wav.write("data", 36);
  wav.writeUInt32LE(data.length * 2, 40);
  data.forEach((value, i) =>
    wav.writeInt16LE(
      Math.round(Math.max(-1, Math.min(1, value)) * 32767),
      44 + i * 2,
    ),
  );
  writeFileSync(new URL(`../assets/audio/${key}.wav`, import.meta.url), wav);
  mapping += `  ${key}: { source: require('../../assets/audio/${key}.wav'), cooldown: ${effect.cooldown} },\n`;
}
writeFileSync(
  new URL("../src/mobile/soundAssets.ts", import.meta.url),
  mapping + "};\n",
);
console.log(`Generated ${Object.keys(EFFECTS).length} offline WAV effects.`);
